function demoMain(idx,label){
  var issues=[["BUG-101","crash on save","open","high"],["FEAT-202","dark mode","in-progress","medium"],["BUG-103","typo in help","closed","low"]];
  var open=issues.filter(function(i){return i[2]!=="closed";}).length;
  var i=issues[idx%issues.length];
  return "["+label+"] "+issues.length+" issues, "+open+" open. Sample: "+i[0]+" ["+i[3]+"] "+i[1]+" ("+i[2]+")";
}

